import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, phone as phoneMq } from "./tokens.stylex";
import { rs } from "./rs";

/** StyleX cannot read a string const from a defineVars file; keep the token import. */
const phone = "@media (max-width: 640px)" as typeof phoneMq;
import { Button } from "./button";

export interface PopoverProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Trigger content, rendered in a ghost button. */
  trigger: React.ReactNode;
  /** Where the panel sits relative to the trigger. */
  align?: "start" | "end";
}

const styles = stylex.create({
  panel: {
    boxSizing: "border-box",
    position: "fixed",
    inset: "auto",
    margin: 0,
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: {
      default: raster.radius,
      [phone]: 0,
    },
    backgroundColor: raster.paper,
    color: raster.ink,
    boxShadow: {
      default: "0 8px 24px rgba(0,0,0,0.06)",
      [phone]: "none",
    },
    padding: {
      default: 14,
      [phone]: 16,
    },
    width: {
      default: 240,
      [phone]: "min(320px, calc(100vw - 32px))",
    },
    fontSize: {
      default: 13,
      [phone]: 16,
    },
    lineHeight: 1.55,
    letterSpacing: "-0.01em",
  },
  title: {
    display: "block",
    fontSize: {
      default: 13,
      [phone]: 16,
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: raster.ink,
    marginBottom: 4,
  },
  body: {
    color: raster.gray,
    margin: 0,
  },
});

/**
 * The native Popover API. The panel lives in the top layer; light
 * dismiss comes from the platform.
 */
export function Popover({ trigger, align = "start", className, style, children, ...props }: PopoverProps) {
  const id = React.useId();
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const [coords, setCoords] = React.useState<{ top: number; left: number } | null>(null);

  const position = () => {
    const anchor = triggerRef.current;
    const panel = panelRef.current;
    if (!anchor || !panel) return;
    const rect = anchor.getBoundingClientRect();
    setCoords({
      top: rect.bottom + 6,
      left:
        align === "end"
          ? Math.max(8, rect.right - panel.offsetWidth)
          : Math.min(rect.left, window.innerWidth - panel.offsetWidth - 8),
    });
  };

  const sx = rs(["rs-popover", className], styles.panel);
  return (
    <>
      <Button ref={triggerRef} type="button" variant="ghost" size="sm" popoverTarget={id}>
        {trigger}
      </Button>
      <div
        ref={panelRef}
        id={id}
        popover="auto"
        className={sx.className}
        style={{ ...sx.style, ...style, ...(coords ? { top: coords.top, left: coords.left } : {}) }}
        onToggle={(e) => {
          if ((e as unknown as ToggleEvent).newState === "open") position();
        }}
        {...props}
      >
        {children}
      </div>
    </>
  );
}

export function PopoverTitle({ className, style, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  const sx = rs(["rs-popover-title", className], styles.title);
  return <span {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function PopoverBody({ className, style, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  const sx = rs(["rs-popover-body", className], styles.body);
  return <p {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Solid ink primary or hairline ghost. One primary per view. */
  variant?: "primary" | "ghost";
  size?: "default" | "sm";
  /** Flush into a ButtonGroup: no own stroke, one ink seam. */
  grouped?: boolean;
}

const styles = stylex.create({
  base: {
    boxSizing: "border-box",
    fontFamily: "inherit",
    letterSpacing: "-0.01em",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    gap: 8,
    cursor: {
      default: "pointer",
      ":disabled": "not-allowed",
    },
    height: {
      default: raster.controlH,
      "@media (max-width: 640px)": raster.controlH,
    },
    minHeight: {
      default: null,
      "@media (max-width: 640px)": raster.hit,
    },
    width: {
      default: null,
      "@media (max-width: 640px)": "100%",
    },
    fontSize: raster.controlFs,
    paddingInline: {
      default: 22,
      "@media (max-width: 640px)": 20,
    },
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderRadius: {
      default: raster.radiusSm,
      "@media (max-width: 640px)": 0,
    },
    transition: "opacity var(--duration-snap) var(--ease), background-color var(--duration-snap) var(--ease), color var(--duration-snap) var(--ease)",
    opacity: {
      default: 1,
      ":hover": 0.85,
      ":disabled": 0.4,
    },
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": raster.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
  },
  primary: {
    fontWeight: 600,
    backgroundColor: raster.ink,
    color: raster.paper,
    borderColor: "transparent",
  },
  ghost: {
    fontWeight: 500,
    backgroundColor: {
      default: "transparent",
      ":hover": raster.divider,
      ":disabled": "transparent",
    },
    color: raster.ink,
    borderColor: {
      default: raster.divider,
      ":hover": "transparent",
      ":disabled": raster.divider,
    },
  },
  sm: {
    height: {
      default: 36,
      "@media (max-width: 640px)": raster.controlH,
    },
    minHeight: {
      default: null,
      "@media (max-width: 640px)": raster.hit,
    },
    paddingInline: {
      default: 14,
      "@media (max-width: 640px)": 16,
    },
    fontSize: {
      default: 13,
      "@media (max-width: 640px)": raster.controlFs,
    },
    minWidth: {
      default: 104,
      "@media (max-width: 640px)": 0,
    },
  },
  grouped: {
    height: "auto",
    minHeight: null,
    width: {
      default: null,
      "@media (max-width: 640px)": null,
    },
    borderWidth: 0,
    borderRadius: 0,
    margin: 0,
    flexGrow: {
      default: null,
      "@media (max-width: 640px)": 1,
    },
    minWidth: {
      default: 0,
      "@media (max-width: 640px)": 0,
    },
  },
  groupedGhost: {
    backgroundColor: {
      default: raster.paper,
      ":hover": raster.divider,
      ":disabled": raster.paper,
    },
  },
});

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  { variant = "primary", size = "default", grouped = false, type = "button", className, style, ...props },
  ref,
) {
  const sx = rs(
    [variant === "ghost" ? "rs-btn-ghost" : "rs-btn-primary", size === "sm" && "rs-btn-sm", className],
    styles.base,
    variant === "ghost" ? styles.ghost : styles.primary,
    size === "sm" && styles.sm,
    grouped && styles.grouped,
    grouped && variant === "ghost" && styles.groupedGhost,
  );
  return <button ref={ref} type={type} {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
});

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
